{
  "title": "Off-by-one loop",
  "language": "JavaScript",
  "objective": "Find a boundary error",
  "prompt": "Why does this loop miss the last item?",
  "codeSnippet": "const items = [1, 2, 3];\nfor (let i = 0; i < items.length - 1; i++) {\n  console.log(items[i]);\n}",
  "questions": [
    {
      "type": "predict-output",
      "prompt": "Which values does the shared loop log, in order, one value per line?",
      "options": [
        {
          "id": "a",
          "label": "1, then 2, then 3"
        },
        {
          "id": "b",
          "label": "1, then 2"
        },
        {
          "id": "c",
          "label": "2, then 3"
        }
      ],
      "acceptedAnswer": "b",
      "explanation": "items.length is 3, so i < 2 visits only indices 0 and 1 and logs 1, then 2."
    },
    {
      "type": "locate-fault",
      "prompt": "Which line contains the fault, and what kind of error is it?",
      "options": [
        {
          "id": "line-1",
          "label": "line 1"
        },
        {
          "id": "line-2",
          "label": "line 2"
        },
        {
          "id": "line-3",
          "label": "line 3"
        },
        {
          "id": "category-1",
          "label": "boundary"
        },
        {
          "id": "category-2",
          "label": "syntax"
        }
      ],
      "acceptedAnswer": {
        "location": "line-2",
        "category": "category-1"
      },
      "explanation": "The loop condition on line 2 stops before the final valid index because it subtracts 1 from items.length."
    },
    {
      "type": "repair-order",
      "prompt": "Put these debugging steps in order, from diagnosing the skipped item to verifying the repair.",
      "options": [
        {
          "id": "s2",
          "label": "Change the condition to i < items.length."
        },
        {
          "id": "s3",
          "label": "Run the loop and verify that it logs 1, then 2, then 3."
        },
        {
          "id": "s1",
          "label": "Trace the loop indices and confirm that the final item is skipped."
        }
      ],
      "acceptedAnswer": [
        "s1",
        "s2",
        "s3"
      ],
      "explanation": "First identify the skipped index, then correct the boundary, then run the loop to verify all three items."
    }
  ],
  "appliedCase": {
    "prompt": "Explain the failure and propose a repair."
  },
  "progressiveHints": [
    "Check the loop bound",
    "Compare with items.length"
  ],
  "explanation": "The loop stops one item early."
}

{
  "appliedDiagnosis": "The loop bound excludes the final element."
}

{
  "title": "Event registration repair",
  "rubric": "Evidence quality and a working repair"
}

{
  "reflection": "The validation failed because the check ran after submit."
}

{
  "title": "Week 3: Loops",
  "bossId": "memory-kraken",
  "hearts": 3,
  "questions": [
    {
      "id": "q1",
      "code": "for i in range(3):\n    print(i)",
      "prompt": "What is the last number printed?",
      "options": [
        {
          "id": "a",
          "label": "2"
        },
        {
          "id": "b",
          "label": "3"
        },
        {
          "id": "c",
          "label": "0"
        }
      ],
      "correctOptionId": "a",
      "explanation": "range(3) stops before 3, so the loop prints 0, 1 and 2.",
      "keepOrder": false
    },
    {
      "id": "q2",
      "code": "",
      "prompt": "Which loop runs at least once?",
      "options": [
        {
          "id": "a",
          "label": "for"
        },
        {
          "id": "b",
          "label": "while"
        },
        {
          "id": "c",
          "label": "do-while"
        }
      ],
      "correctOptionId": "c",
      "explanation": "A do-while checks its condition after the body runs.",
      "keepOrder": false
    },
    {
      "id": "q3",
      "code": "i = 0\nwhile i < 5:\n    print(i)",
      "prompt": "Why does this loop never stop?",
      "options": [
        {
          "id": "a",
          "label": "i never changes"
        },
        {
          "id": "b",
          "label": "5 is too big"
        },
        {
          "id": "c",
          "label": "print returns None"
        }
      ],
      "correctOptionId": "a",
      "explanation": "Nothing in the body changes i, so i < 5 stays true.",
      "keepOrder": false
    }
  ]
}
